theorem Tengoku.LeanSpectralTheory.PVM.monotone (E_pvm : PVM E) {S T : Set ℝ}
    (hS : MeasurableSet S) (hT : MeasurableSet T) (h : S ⊆ T) (x : E) :
    (@inner ℂ E _ (E_pvm.proj S x) x).re ≤ (@inner ℂ E _ (E_pvm.proj T x) x).re

theorem Tengoku.LeanSpectralTheory.PVM.proj_union (E_pvm : PVM E) {S T : Set ℝ}
    (hS : MeasurableSet S) (hT : MeasurableSet T) (hdisj : Disjoint S T) :
    E_pvm.proj (S ∪ T) = E_pvm.proj S + E_pvm.proj T

theorem Tengoku.LeanSpectralTheory.PVM.norm_simpleIntegral_sub_le (E_pvm : PVM E) (f g : SimpleFunc ℝ ℂ) {C : ℝ}
    (hbdd : ∀ t, ‖f t - g t‖ ≤ C) :
    ‖E_pvm.simpleIntegral f - E_pvm.simpleIntegral g‖ ≤ C

theorem Tengoku.LeanSpectralTheory.PVM.sum_proj_preimage (E_pvm : PVM E) {β : Type*}
    (f : SimpleFunc ℝ β) (s : Finset β) :
    ∑ y ∈ s, E_pvm.proj (f ⁻¹' {y}) = E_pvm.proj (f ⁻¹' (↑s : Set β))
